phases.enterFn:
e=>{ if (G.split) return; G.split = true; e.name = 'Face of the Congregation'; const ts = shuffled(targetsForFoes());
                 for (let i=0;i<2;i++){ const f = spawnPart(e, 'congregation', SLOT*(2+i)); f.parentId = null; f.name = 'Face of the Congregation'; f.maxhp = f.hp = Math.round(e.maxhp*.3); f.phase = 'p2'; f.stare = null; }
                 const faces = G.enemies.filter(x=>x.key==='congregation' && x.alive); faces.forEach(f=>{ f.stare = null; });
                 faces.forEach((f,i)=>{ f.stare = (ts[i] || pick(targetsForFoes())).id; });
                 log(`The Congregation splits into 3 Faces: they stare at ${faces.map(f=>byId(f.stare).name).join(', ')}.`, 'foe'); }
